create table if not exists public.accounting_books(accounting_book_id bigint generated always as identity primary key,book_name text not null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),base_currency_id bigint not null references public.currencies(currency_id),is_primary boolean not null default false,is_active boolean not null default true,unique(book_name,subsidiary_id));
create table if not exists public.account_group(group_id bigint generated always as identity primary key,group_code text not null unique,group_name text not null,category text not null);
create table if not exists public.chart_accounts(account_id bigint generated always as identity primary key,account_number text not null unique,account_name text not null,account_type text not null,parent_id bigint references public.chart_accounts(account_id) on delete set null,currency_id bigint references public.currencies(currency_id),account_group_id bigint not null references public.account_group(group_id),is_summary boolean not null default false,is_inactive boolean not null default false);
create table if not exists public.account_subsidiaries(id bigint generated always as identity primary key,account_id bigint not null references public.chart_accounts(account_id) on delete cascade,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id) on delete cascade,is_active boolean not null default true,unique(account_id,subsidiary_id));
create table if not exists public.budget(budget_id bigint generated always as identity primary key,budget_name text not null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),fiscal_year_id bigint not null references public.fiscal_years(fiscal_year_id),accounting_book_id bigint not null references public.accounting_books(accounting_book_id),unique(budget_name,subsidiary_id,fiscal_year_id,accounting_book_id));
create table if not exists public.budget_line(budget_line_id bigint generated always as identity primary key,budget_id bigint not null references public.budget(budget_id) on delete cascade,account_id bigint not null references public.chart_accounts(account_id),period_id bigint not null references public.fiscal_periods(fiscal_period_id),amount numeric(24,6) not null,department_id bigint references public.departments(department_id),class_id bigint references public.classes(class_id),unique(budget_id,account_id,period_id,department_id,class_id));
create table if not exists public.allocation_rules(rule_id bigint generated always as identity primary key,rule_name text not null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),source_account_id bigint not null references public.chart_accounts(account_id),target_account_id bigint not null references public.chart_accounts(account_id),allocation_percentage numeric(9,5) not null check(allocation_percentage>0 and allocation_percentage<=100),unique(rule_name,subsidiary_id),check(source_account_id<>target_account_id));
do $$ declare t text;begin foreach t in array array['accounting_books','account_group','chart_accounts','account_subsidiaries','budget','budget_line','allocation_rules']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "accounting_select" on public.%I',t);execute format('drop policy if exists "accounting_insert" on public.%I',t);execute format('drop policy if exists "accounting_update" on public.%I',t);execute format('drop policy if exists "accounting_delete" on public.%I',t);execute format('create policy "accounting_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "accounting_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "accounting_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "accounting_delete" on public.%I for delete to authenticated using(true)',t);end loop;end $$;
